/** Public Mapzen Terrain Tiles reference, resampled locally.
 * Europe: Produced using Copernicus data and information funded by the European Union – EU-DEM layers.
 * GMTED2010/SRTM: U.S. Geological Survey. See public/terrain/alpine-dem-source.json and alpine-dem-attribution.md.
 * Local rendering reference, not a precise survey or photogrammetric scan.
 */
const GRID = 601;
const packed = '';
const bytes = Uint8Array.from(atob(packed), c => c.charCodeAt(0));
const samples = new DataView(bytes.buffer);
export const ALPINE_DEM_BOUNDS = { width: 12000, depth: 13500, centerZ: -4750 };
export function alpineElevation(x: number, z: number) {
  const u = Math.max(0, Math.min(GRID - 1.000001, (x + 6000) / 12000 * (GRID - 1)));
  const v = Math.max(0, Math.min(GRID - 1.000001, (z + 11500) / 13500 * (GRID - 1)));
  const ix = Math.floor(u), iz = Math.floor(v), fx = u - ix, fz = v - iz;
  const at = (a: number, b: number) => samples.getUint16((b * GRID + a) * 2, true) * .25;
  return at(ix, iz)*(1-fx)*(1-fz) + at(ix+1,iz)*fx*(1-fz) + at(ix,iz+1)*(1-fx)*fz + at(ix+1,iz+1)*fx*fz;
}
